import test from 'node:test';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {readFile} from 'node:fs/promises';import {validateFinalAuditMetadata as verify} from '../scripts/final-audit-metadata.mjs';
const sha=x=>createHash('sha256').update(typeof x==='string'?x:JSON.stringify(x)).digest('hex');
const before=[{id:'x',items:[{id:'q',q:'Question',a:'old',lead:'old'}]}],after=[{id:'x',items:[{id:'q',q:'Question',a:'new',lead:'new'}]}],card={rows:[['condition','answer']]},metadata={HL:{cards:{'x#0':card}}},record={key:'x#0',questionId:'q',questionText:'Question',answerSha256:sha('new'),leadSha256:sha('new'),cardSha256:sha(card)},registry={schemaVersion:1,records:[record]};
test('changed question/card requires explicit exact paired semantic review',()=>{assert.deepEqual(verify(metadata,before,after,registry),metadata);assert.throws(()=>verify(metadata,before,after,{schemaVersion:1,records:[]}),/unreviewed/);});
test('paired review rejects answer, card and stable identity drift',()=>{for(const mutate of [x=>x[0].items[0].a+='x',x=>x[0].items[0].lead+='x',x=>x[0].items[0].q+='x',x=>x[0].items[0].id+='x']){const a=structuredClone(after);mutate(a);assert.throws(()=>verify(metadata,before,a,registry),/drift/);}const m=structuredClone(metadata);m.HL.cards['x#0'].rows.push(['x','y']);assert.throws(()=>verify(m,before,after,registry),/drift/);});
test('unused and duplicate reviews cannot silently satisfy an unchanged question',()=>{assert.throws(()=>verify(metadata,before,before,registry),/unused/);assert.throws(()=>verify(metadata,before,after,{schemaVersion:1,records:[record,record]}),/duplicate/);});
test('current Kafka card is bound to final answer while original guard retains original input',async()=>{const src=await readFile(new URL('../scripts/build.mjs',import.meta.url),'utf8');assert.ok(src.includes('projectReviewedComparisonMetadata'));assert.match(src,/projectReviewedComparisonMetadata\([^;]+practiceEntries/s);const r=JSON.parse(await readFile(new URL('../content/final-audit-comparison-review.json',import.meta.url),'utf8'));assert.deepEqual(r.records.map(x=>x.key),["bg-kafka-3#1","ai-模型与评测-3#1","ai-模型与评测-6#2","ai-模型与评测-2#0","ai-模型与评测-5#4","ai-模型与评测-7#1","ai-模型与评测-7#2","ai-模型与评测-8#1","ai-agent-2#6","ai-agent-2#7","ai-agent-3#2","ai-agent-3#3","ai-agent-2#5","ai-agent-2#10","ai-agent-2#12","ai-agent-3#0","ai-agent-3#1","ai-模型与评测-4#2","ai-模型与评测-4#3","ai-模型与评测-4#4","ai-模型与评测-4#11","ai-模型与评测-4#0","ai-模型与评测-3#3","ai-模型与评测-3#6","ai-agent-6#4","ai-agent-6#9","ai-agent-6#11","ai-agent-6#12","ai-模型与评测-6#0","ai-模型与评测-7#0"]);assert.equal(r.records[0].key,'bg-kafka-3#1');const catalog=JSON.parse(await readFile(new URL('../dist/data/catalog.json',import.meta.url),'utf8'));const e=catalog.entries.find(e=>e.id==='bg-kafka-3');const actual=JSON.parse(await readFile(new URL('../dist/'+e._chunk,import.meta.url),'utf8')).entries.find(v=>v.id==='bg-kafka-3').items[1];assert.equal(sha(actual.a),r.records[0].answerSha256);assert.equal(sha(actual.lead),r.records[0].leadSha256);for(const review of r.records){const [id,n]=review.key.split('#');const meta=catalog.entries.find(e=>e.id===id);const item=JSON.parse(await readFile(new URL('../dist/'+meta._chunk,import.meta.url),'utf8')).entries.find(e=>e.id===id).items[Number(n)];assert.equal(item.q,review.questionText);assert.equal(item.id??null,review.questionId);assert.equal(sha(item.a),review.answerSha256);assert.equal(sha(item.lead||''),review.leadSha256);assert.equal(sha(catalog.HL.cards[review.key]),review.cardSha256);}});
test('reviewed card correction is exact, cloned and rejects stale input',()=>{const newCard={rows:[['condition','qualified answer']]},review={...record,inputCardSha256:sha(card),newCard,cardSha256:sha(newCard)};const r={schemaVersion:1,records:[review]};assert.deepEqual(verify(metadata,before,after,r).HL.cards['x#0'],newCard);assert.deepEqual(metadata.HL.cards['x#0'],card);assert.throws(()=>verify(metadata,before,after,{schemaVersion:1,records:[{...review,inputCardSha256:'bad'}]}),/input card drift/);assert.throws(()=>verify(metadata,before,after,{schemaVersion:1,records:[{...review,cardSha256:'bad'}]}),/paired review drift/);});

